				dp[i][j] = MinInt(MinInt(dp[i][j-1], dp[i-1][j]), dp[i-1][j-1]) + 1
			}
		}
	}
	return dp[n][m]
}

/* 编辑距离：空间优化后的动态规划 */
func editDistanceDPComp(s string, t string) int {
	n := len(s)
