		dp[j] = j
	}
	// 状态转移：其余行
	for i := 1; i <= n; i++ {
		// 状态转移：首列
		leftUp := dp[0] // 暂存 dp[i-1, j-1]
		dp[0] = i
		// 状态转移：其余列
		for j := 1; j <= m; j++ {
			temp := dp[j]
			if s[i-1] == t[j-1] {
				// 若两字符相等，则直接跳过此两字符
